1	using Microsoft.EntityFrameworkCore;
2	using seed_a_backend.Api.Infrastructure;
3	
4	namespace seed_a_backend.Tests;
5	
6	public class SeedDataImporterTests : IAsyncLifetime
7	{
8	    private readonly SqlServerTestDatabase _database = new();
9	
10	    public ValueTask InitializeAsync() => _database.InitializeAsync();
11	
12	    public ValueTask DisposeAsync() => _database.DisposeAsync();
13	
14	    /// <summary>
15	    /// Dedizierte Test-Fixture, unabhängig vom Produktions-Anfangsdatenbestand — inhaltliche
16	    /// Änderungen an der Produktions-Seed-Datei dürfen diese Tests nicht brechen.
17	    /// </summary>
18	    private static string SeedFilePath() => Path.Combine(AppContext.BaseDirectory, "TestData", "seed-fixture.json");
19	
20	    [Fact]
21	    public async Task ImportIfEmptyAsync_gegen_leere_DB_befuellt_alle_Tabellen_korrekt()
22	    {
23	        var ct = TestContext.Current.CancellationToken;
24	        await using var db = _database.CreateContext();
25	        var importer = new SeedDataImporter(db);
26	
27	        await importer.ImportIfEmptyAsync(SeedFilePath(), ct);
28	
29	        Assert.Equal(2, await db.Venues.CountAsync(ct));
30	        Assert.Equal(3, await db.Rooms.CountAsync(ct));
31	        Assert.Equal(2, await db.Events.CountAsync(ct));
32	        Assert.Equal(4, await db.PriceCategories.CountAsync(ct));
33	
34	        var kleinerSaal = await db.Rooms.SingleAsync(r => r.Name == "Kleiner Saal", ct);
35	        Assert.Equal(new[] { "A", "B", "C", "D", "E", "F" }, kleinerSaal.RowLabels);
36	        Assert.Equal(10, kleinerSaal.ColumnCount);
37	        Assert.Equal(new[] { 6 }, kleinerSaal.AisleColumns);
38	
39	        var studio = await db.Rooms.SingleAsync(r => r.Name == "Studio", ct);
40	        Assert.Empty(studio.AisleColumns);
41	
42	        var kammerkonzert = await db.Events.SingleAsync(e => e.Titel == "Kammerkonzert Fruehling", ct);
43	
44	        var preiskategorien = await db.PriceCategories
45	            .Where(pc => pc.EventId == kammerkonzert.Id)
46	            .OrderBy(pc => pc.Name)
47	            .ToListAsync(ct);
48	        Assert.Collection(preiskategorien,
49	            pc => { Assert.Equal("Kategorie A", pc.Name); Assert.Equal(32.00m, pc.Preis); },
50	            pc => { Assert.Equal("Kategorie B", pc.Name); Assert.Equal(22.00m, pc.Preis); });
51	
52	        var belegtePositionen = await db.BookingPositions
53	            .Where(bp => bp.EventId == kammerkonzert.Id)
54	            .OrderBy(bp => bp.RowLabel).ThenBy(bp => bp.ColumnNumber)
55	            .ToListAsync(ct);
56	
57	        Assert.Equal(3, belegtePositionen.Count);
58	        Assert.Collection(belegtePositionen,
59	            p => Assert.Equal(("B", 3), (p.RowLabel, p.ColumnNumber)),
60	            p => Assert.Equal(("B", 4), (p.RowLabel, p.ColumnNumber)),
61	            p => Assert.Equal(("C", 7), (p.RowLabel, p.ColumnNumber)));
62	
63	        Assert.All(belegtePositionen, p =>
64	        {
65	            Assert.Null(p.BookingId);
66	            Assert.Null(p.PriceCategoryId);
67	            Assert.Null(p.CancelledAtUtc);
68	        });
69	
70	        var sinfonisches = await db.Events.SingleAsync(e => e.Titel == "Sinfonisches Openair-Programm", ct);
71	        var keinePositionen = await db.BookingPositions.Where(bp => bp.EventId == sinfonisches.Id).CountAsync(ct);
72	        Assert.Equal(0, keinePositionen);
73	    }
74	
75	    [Fact]
76	    public async Task ImportIfEmptyAsync_zweiter_Lauf_gegen_befuellte_DB_erzeugt_keine_Duplikate()
77	    {
78	        var ct = TestContext.Current.CancellationToken;
79	        await using var db = _database.CreateContext();
80	        var importer = new SeedDataImporter(db);
81	        var seedFilePath = SeedFilePath();
82	
83	        await importer.ImportIfEmptyAsync(seedFilePath, ct);
84	        var venuesNachErstemLauf = await db.Venues.CountAsync(ct);
85	        var eventsNachErstemLauf = await db.Events.CountAsync(ct);
86	        var positionenNachErstemLauf = await db.BookingPositions.CountAsync(ct);
87	
88	        await importer.ImportIfEmptyAsync(seedFilePath, ct);
89	
90	        Assert.Equal(venuesNachErstemLauf, await db.Venues.CountAsync(ct));
91	        Assert.Equal(eventsNachErstemLauf, await db.Events.CountAsync(ct));
92	        Assert.Equal(positionenNachErstemLauf, await db.BookingPositions.CountAsync(ct));
93	    }
94	
95	    [Fact]
96	    public async Task Gefilterte_Unique_Constraint_verhindert_doppelte_aktive_Belegung_desselben_Sitzplatzes()
97	    {
98	        var ct = TestContext.Current.CancellationToken;
99	        await using var db = _database.CreateContext();
100	        var importer = new SeedDataImporter(db);
101	        await importer.ImportIfEmptyAsync(SeedFilePath(), ct);
102	
103	        var kammerkonzert = await db.Events.SingleAsync(e => e.Titel == "Kammerkonzert Fruehling", ct);
104	
105	        db.BookingPositions.Add(new Api.Domain.BookingPosition
106	        {
107	            EventId = kammerkonzert.Id,
108	            RowLabel = "B",
109	            ColumnNumber = 3,
110	            BookingId = null,
111	            PriceCategoryId = null,
112	            CancelledAtUtc = null,
113	        });
114	
115	        await Assert.ThrowsAsync<DbUpdateException>(() => db.SaveChangesAsync(ct));
116	    }
117	
118	    [Fact]
119	    public async Task Nach_Stornierung_kann_derselbe_Sitzplatz_erneut_belegt_werden()
120	    {
121	        var ct = TestContext.Current.CancellationToken;
122	        await using var db = _database.CreateContext();
123	        var importer = new SeedDataImporter(db);
124	        await importer.ImportIfEmptyAsync(SeedFilePath(), ct);
125	
126	        var kammerkonzert = await db.Events.SingleAsync(e => e.Titel == "Kammerkonzert Fruehling", ct);
127	        var stornierterPlatz = await db.BookingPositions.SingleAsync(
128	            bp => bp.EventId == kammerkonzert.Id && bp.RowLabel == "B" && bp.ColumnNumber == 3, ct);
129	        stornierterPlatz.CancelledAtUtc = DateTime.UtcNow;
130	        await db.SaveChangesAsync(ct);
131	
132	        db.BookingPositions.Add(new Api.Domain.BookingPosition
133	        {
134	            EventId = kammerkonzert.Id,
135	            RowLabel = "B",
136	            ColumnNumber = 3,
137	            BookingId = null,
138	            PriceCategoryId = null,
139	            CancelledAtUtc = null,
140	        });
141	
142	        await db.SaveChangesAsync(ct);
143	
144	        var aktiveBelegungen = await db.BookingPositions.CountAsync(
145	            bp => bp.EventId == kammerkonzert.Id && bp.RowLabel == "B" && bp.ColumnNumber == 3 && bp.CancelledAtUtc == null, ct);
146	        Assert.Equal(1, aktiveBelegungen);
147	    }
148	
149	    [Fact]
150	    public async Task PriceCategory_Preis_wird_gemaess_HasPrecision_10_2_auf_zwei_Nachkommastellen_gerundet()
151	    {
152	        var ct = TestContext.Current.CancellationToken;
153	        await using var db = _database.CreateContext();
154	        var importer = new SeedDataImporter(db);
155	        await importer.ImportIfEmptyAsync(SeedFilePath(), ct);
156	        var kammerkonzert = await db.Events.SingleAsync(e => e.Titel == "Kammerkonzert Fruehling", ct);
157	
158	        db.PriceCategories.Add(new Api.Domain.PriceCategory
