import { chromium } from 'playwright';

const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on('console', msg => { if (msg.type() === 'error') errors.push(msg.text()); });
page.on('pageerror', err => errors.push(String(err)));

await page.goto('http://localhost:4200', { waitUntil: 'networkidle' });
await page.waitForSelector('text=Kammerkonzert Frühling', { timeout: 15000 });
await page.screenshot({ path: '/tmp/desktop.png', fullPage: true });

await page.setViewportSize({ width: 375, height: 800 });
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/mobile.png', fullPage: true });

await page.click('text=Buchung abrufen');
await page.waitForSelector('text=Buchung abrufen', { timeout: 5000 });
await page.screenshot({ path: '/tmp/booking-lookup.png', fullPage: true });

console.log('ERRORS:', JSON.stringify(errors));
await browser.close();
EOF
